const b = $input.first().json;
const x = b.ctx || {};
const sev = ({ Critical: ['🚨 CRITICAL', 0xE74C3C], High: ['⚠️ HIGH', 0xE67E22], Medium: ['🟡 MEDIUM', 0xF1C40F], Low: ['🔵 LOW', 0x3498DB] })[b.severity || ({ S7: 'Critical', S1: 'High', S4: 'High', S10: 'High', S12: 'High', S8: 'Medium', H1: 'Medium' })[b.case_id] || 'Low'];
const results = x.results || [];
const pct = (ok, total) => total ? `${Math.round(ok / total * 100)}% (${ok}/${total})` : '—';
const response_rate = pct(results.filter(r => ['applied', 'already_applied', 'released'].includes(r.result)).length, results.length);
const recovery = x.recovery?.samples || [];
const recovery_rate = pct(recovery.filter(r => r.ok).length, recovery.length);
const title = `${sev[0]} · [${b.case_id || '-'}] ${b.title || '보안 티켓'}`;
const fields = [
 { name: '🎯 대상', value: b.src_ip || x.username || '-', inline: true },
 { name: '📌 티켓', value: b.ticket_id || '-', inline: true },
 { name: '⚡ 대응 성공률', value: response_rate, inline: true },
 { name: '🩺 복구 성공률', value: recovery_rate, inline: true },
 { name: '📍 상태', value: b.level === 'error' ? '⛔ 사람 확인 필요' : '✅ 자동 대응 처리', inline: false }
];
return [{ json: { content: `${sev[0]} ${b.case_id || '-'} ${b.src_ip || ''}`.trim(), embed: { title, color: sev[1], fields, footer: { text: `해담 SOAR · n8n 실행 ${$execution.id}` }, timestamp: new Date().toISOString() }, ctx: b.ctx } }];

// Discord 노드 결과(또는 자격 증명 없음·전송 실패)를 sent 여부로 정리
const j = $input.first().json;
const failed = !!(j.error || (j.message && /credential|webhook|ENOTFOUND|\b4\d\d\b/i.test(String(j.message))));
return [{ json: { sent: !failed, error: failed ? String((j.error && j.error.message) || j.message || j.error) : null, ctx: $('Discord 본문').first().json.ctx } }];
